function u(t){const n=typeof t=="bigint"?Number(t):t;if(Number.isNaN(n))return"₹ 0";const o=n<0,r=Math.abs(Math.round(n)).toString();if(r.length<=3)return`${o?"-":""}₹ ${r}`;const a=r.slice(-3),i=r.slice(0,-3);let e="";for(let s=i.length;s>0;s-=2){const c=Math.max(0,s-2);e=i.slice(c,s)+(e?`,${e}`:"")}return`${o?"-":""}₹ ${e},${a}`}function m(t){const n=typeof t=="bigint"?Number(t):t;return u(n/100)}export{m as a,u as f};
